import { Question } from "@/lib/types";

/**
 * Year 2 — Integration (Y2) § 11.1 Integrating Standard Functions
 * Ref: y2in1
 * 71 questions: standard integrals of \\(x^n, e^{kx}, \\sin, \\cos, 1/x,
 * \\sec^2, \\sec\\tan, \\csc^2, \\csc\\cot\\) and definite integrals.
 *
 * Worked solutions massively expanded — each step names its move, applies it,
 * and explains why with watch-outs for common slips. Question 1 uses
 * \\displaystyle\\int (big integral signs) throughout to match its stem;
 * the rest use plain \\displaystyle\\int matching their stems.
 */
export const questions: Question[] = [
  { id: "y2in1-001", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 01", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(e^x + \\sin x\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["integration", "standard"], workedSolution: { steps: [ { stepNumber: 1, description: "Split the integral term by term.", workingLatex: "\\displaystyle\\int (e^x + \\sin x)\\,dx \\;=\\; \\displaystyle\\int e^x\\,dx \\;+\\; \\displaystyle\\int \\sin x\\,dx", explanation: "Integration is linear, so a sum inside the integral splits into a sum of separate integrals. Doing this first avoids juggling two antiderivatives at once." }, { stepNumber: 2, description: "Apply the standard antiderivative for each term.", workingLatex: "\\displaystyle\\int e^x\\,dx = e^x, \\qquad \\displaystyle\\int \\sin x\\,dx = -\\cos x", explanation: "\\(e^x\\) is its own derivative, so it is also its own antiderivative. For sine, \\(\\frac{d}{dx}(-\\cos x) = \\sin x\\), so the antiderivative of \\(\\sin x\\) is \\(-\\cos x\\) — the minus sign is the most common slip here." }, { stepNumber: 3, description: "Combine and add the constant of integration.", workingLatex: "\\displaystyle\\int (e^x + \\sin x)\\,dx \\;=\\; e^x - \\cos x + C", explanation: "Two separate constants of integration always collapse into a single \\(+C\\). Finish every indefinite integral with one \\(+C\\)." } ], finalAnswer: "\\(e^x - \\cos x + C\\)." } },
  { id: "y2in1-002", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 02", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int x^3 \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the power rule.", workingLatex: "\\displaystyle\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C, \\quad n \\ne -1", explanation: "Increase the exponent by one and divide by the new exponent. The rule is valid for every real \\(n\\) except \\(n = -1\\), where dividing by zero would fail (that case gives \\(\\ln|x|\\) instead)." }, { stepNumber: 2, description: "Substitute \\(n = 3\\).", workingLatex: "\\displaystyle\\int x^3\\,dx = \\frac{x^{4}}{4} + C", explanation: "\\(n+1 = 4\\) in both the exponent and the denominator. Always remember the \\(+C\\) on an indefinite integral." } ], finalAnswer: "\\(\\frac{x^4}{4} + C\\)." } },
  { id: "y2in1-003", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 03", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 5x^2 \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Pull the constant out of the integral.", workingLatex: "\\displaystyle\\int 5x^2\\,dx = 5\\displaystyle\\int x^2\\,dx", explanation: "Constant multiples factor straight out of an integral, just as they do for derivatives. It is easier to apply the power rule once than to drag the \\(5\\) along through every step." }, { stepNumber: 2, description: "Apply the power rule with \\(n = 2\\).", workingLatex: "5\\displaystyle\\int x^2\\,dx = 5 \\cdot \\frac{x^{3}}{3} + C", explanation: "\\(n+1 = 3\\). The constant from \\(\\displaystyle\\int x^2\\,dx\\) and the leading \\(5\\) multiply together." }, { stepNumber: 3, description: "Simplify.", workingLatex: "= \\frac{5x^3}{3} + C", explanation: "Combine the \\(5\\) with the \\(\\frac{1}{3}\\). Always finish with \\(+C\\)." } ], finalAnswer: "\\(\\frac{5x^3}{3} + C\\)." } },
  { id: "y2in1-004", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 04", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int x^{-2} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Confirm the power rule applies.", workingLatex: "\\displaystyle\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C \\quad (n \\ne -1)", explanation: "Here \\(n = -2 \\ne -1\\), so the power rule is in scope. The exception is only when \\(n = -1\\) (where you would divide by zero in the formula)." }, { stepNumber: 2, description: "Substitute \\(n = -2\\).", workingLatex: "\\displaystyle\\int x^{-2}\\,dx = \\frac{x^{-2+1}}{-2+1} + C = \\frac{x^{-1}}{-1} + C", explanation: "\\(n+1 = -1\\) in both places. Keeping the formula in symbolic form before plugging in helps avoid sign errors." }, { stepNumber: 3, description: "Tidy up the algebra.", workingLatex: "= -x^{-1} + C = -\\frac{1}{x} + C", explanation: "Convert the negative power back to a fraction: \\(x^{-1} = \\frac{1}{x}\\). The leading minus sign comes from dividing by \\(-1\\)." } ], finalAnswer: "\\(-\\frac{1}{x} + C\\)." } },
  { id: "y2in1-005", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 05", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sqrt x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the radical as a fractional power.", workingLatex: "\\sqrt{x} = x^{\\tfrac{1}{2}}", explanation: "The power rule needs the integrand in the form \\(x^n\\). \\(\\sqrt{x} = x^{\\tfrac{1}{2}}\\) is the standard rewrite for square roots." }, { stepNumber: 2, description: "Apply the power rule with \\(n = \\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int x^{\\tfrac{1}{2}}\\,dx = \\frac{x^{\\tfrac{1}{2} + 1}}{1/2 + 1} + C = \\frac{x^{\\tfrac{3}{2}}}{3/2} + C", explanation: "\\(n+1 = \\frac{3}{2}\\). Be careful with the fractional exponent — students often add \\(\\frac{1}{2}\\) to itself and write \\(x^{1}\\) by mistake." }, { stepNumber: 3, description: "Simplify the compound fraction.", workingLatex: "= \\frac{2}{3}x^{\\tfrac{3}{2}} + C", explanation: "Dividing by \\(\\frac{3}{2}\\) is the same as multiplying by \\(\\frac{2}{3}\\). The answer is now in its tidiest form." } ], finalAnswer: "\\(\\frac{2}{3}x^{\\tfrac{3}{2}} + C\\)." } },
  { id: "y2in1-006", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 06", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 3x^{\\tfrac{1}{3}} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Pull the constant outside the integral.", workingLatex: "\\displaystyle\\int 3x^{\\tfrac{1}{3}}\\,dx = 3\\displaystyle\\int x^{\\tfrac{1}{3}}\\,dx", explanation: "Constants slide through integral signs. This lets us focus on \\(\\displaystyle\\int x^{\\tfrac{1}{3}}\\,dx\\) and tack the \\(3\\) back on at the end." }, { stepNumber: 2, description: "Apply the power rule with \\(n = \\frac{1}{3}\\).", workingLatex: "3\\displaystyle\\int x^{\\tfrac{1}{3}}\\,dx = 3 \\cdot \\frac{x^{\\tfrac{1}{3} + 1}}{1/3 + 1} + C = 3 \\cdot \\frac{x^{\\tfrac{4}{3}}}{4/3} + C", explanation: "\\(\\frac{1}{3} + 1 = \\frac{4}{3}\\). Keep the fractional exponent symbolic — converting to decimals here loses the exact form." }, { stepNumber: 3, description: "Combine the constants.", workingLatex: "= 3 \\cdot \\frac{3}{4} x^{\\tfrac{4}{3}} + C = \\frac{9}{4}x^{\\tfrac{4}{3}} + C", explanation: "Dividing by \\(\\frac{4}{3}\\) is multiplying by \\(\\frac{3}{4}\\); then \\(3 \\cdot \\frac{3}{4} = \\frac{9}{4}\\)." } ], finalAnswer: "\\(\\frac{9}{4}x^{\\tfrac{4}{3}} + C\\)." } },
  { id: "y2in1-007", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 07", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(4x^5 - 2x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Split the integral term by term.", workingLatex: "\\displaystyle\\int (4x^5 - 2x)\\,dx = 4\\displaystyle\\int x^5\\,dx - 2\\displaystyle\\int x\\,dx", explanation: "Linearity of integration lets us split a polynomial integrand and pull each constant coefficient out. This reduces the problem to two single-monomial integrals." }, { stepNumber: 2, description: "Apply the power rule to each.", workingLatex: "4 \\cdot \\frac{x^{6}}{6} - 2 \\cdot \\frac{x^{2}}{2} + C", explanation: "For \\(x^5\\): \\(n+1 = 6\\). For \\(x\\): \\(n+1 = 2\\). Only one \\(+C\\) is needed since the two constants combine." }, { stepNumber: 3, description: "Simplify.", workingLatex: "= \\frac{2x^6}{3} - x^2 + C", explanation: "\\(\\frac{4}{6} = \\frac{2}{3}\\) and \\(\\frac{2}{2} = 1\\). Always check the simplification of fractional coefficients at the end." } ], finalAnswer: "\\(\\frac{2x^6}{3} - x^2 + C\\)." } },
  { id: "y2in1-008", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 08", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(x + 1\\right)^2 \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Expand the bracket — do NOT try a chain-rule substitution.", workingLatex: "(x+1)^2 = x^2 + 2x + 1", explanation: "At this stage we use the standard antiderivatives, which require a polynomial integrand term-by-term. Expand the square so each term is a simple power of \\(x\\). (You could also substitute \\(u = x+1\\) and use \\(\\frac{1}{3}u^3\\) — both routes give equivalent answers.)" }, { stepNumber: 2, description: "Split into three integrals.", workingLatex: "\\displaystyle\\int (x^2 + 2x + 1)\\,dx = \\displaystyle\\int x^2\\,dx + 2\\displaystyle\\int x\\,dx + \\displaystyle\\int 1\\,dx", explanation: "Linearity again: each term integrates separately. Constants factor out." }, { stepNumber: 3, description: "Apply the power rule to each.", workingLatex: "= \\frac{x^3}{3} + 2 \\cdot \\frac{x^2}{2} + x + C", explanation: "\\(\\displaystyle\\int x^2\\,dx = \\frac{x^3}{3}\\); \\(\\displaystyle\\int x\\,dx = \\frac{x^2}{2}\\); \\(\\displaystyle\\int 1\\,dx = x\\). The \\(2 \\cdot \\frac{x^2}{2}\\) tidies to \\(x^2\\)." }, { stepNumber: 4, description: "Simplify.", workingLatex: "= \\frac{x^3}{3} + x^2 + x + C", explanation: "This is the expanded antiderivative. The equivalent compact form \\(\\frac{1}{3}(x+1)^3 + C\\) differs only by an additive constant absorbed into \\(C\\)." } ], finalAnswer: "\\(\\frac{x^3}{3} + x^2 + x + C\\)." } },
  { id: "y2in1-009", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 09", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the defining property of \\(e^x\\).", workingLatex: "\\frac{d}{dx}(e^x) = e^x", explanation: "\\(e^x\\) is special: it is the unique function (up to a constant multiple) whose derivative equals itself. This makes integrating it almost trivial." }, { stepNumber: 2, description: "Read off the antiderivative and append \\(+C\\).", workingLatex: "\\displaystyle\\int e^x\\,dx = e^x + C", explanation: "\\(e^x\\) is therefore its own antiderivative. The arbitrary \\(C\\) reminds you that every vertical translate \\(e^x + C\\) also has derivative \\(e^x\\)." } ], finalAnswer: "\\(e^x + C\\)." } },
  { id: "y2in1-010", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 10", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 2e^x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the constant out.", workingLatex: "\\displaystyle\\int 2e^x\\,dx = 2\\displaystyle\\int e^x\\,dx", explanation: "Constant multiples factor through integrals. This isolates the standard form \\(\\displaystyle\\int e^x\\,dx\\)." }, { stepNumber: 2, description: "Apply the standard result.", workingLatex: "= 2(e^x + C_0) = 2e^x + C", explanation: "\\(\\displaystyle\\int e^x\\,dx = e^x + C_0\\); absorbing \\(2C_0\\) into the single constant \\(C\\) gives the clean form." } ], finalAnswer: "\\(2e^x + C\\)." } },
  { id: "y2in1-011", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 11", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^{2x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Recognise the chain-rule-on-the-inside pattern.", workingLatex: "\\frac{d}{dx}(e^{2x}) = 2e^{2x}", explanation: "Differentiating \\(e^{2x}\\) brings down a factor of \\(2\\), so an antiderivative will need to cancel that \\(2\\) by a factor of \\(\\frac{1}{2}\\) out front." }, { stepNumber: 2, description: "Try \\(F(x) = \\frac{1}{2}e^{2x}\\) and verify.", workingLatex: "\\frac{d}{dx}\\!\\left(\\frac{1}{2}e^{2x}\\right) = \\frac{1}{2} \\cdot 2e^{2x} = e^{2x}", explanation: "Verification: differentiating \\(\\frac{1}{2}e^{2x}\\) gives \\(e^{2x}\\) exactly. The general rule worth remembering is \\(\\displaystyle\\int e^{kx}\\,dx = \\frac{1}{k}e^{kx} + C\\)." }, { stepNumber: 3, description: "Write the antiderivative with \\(+C\\).", workingLatex: "\\displaystyle\\int e^{2x}\\,dx = \\frac{1}{2}e^{2x} + C", explanation: "Always finish with the constant of integration." } ], finalAnswer: "\\(\\frac{1}{2}e^{2x} + C\\)." } },
  { id: "y2in1-012", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 12", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^{-x} \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the rule \\(\\displaystyle\\int e^{kx}\\,dx = \\frac{1}{k}e^{kx} + C\\) with \\(k = -1\\).", workingLatex: "\\displaystyle\\int e^{-x}\\,dx = \\frac{1}{-1}e^{-x} + C", explanation: "The factor \\(\\frac{1}{k}\\) is the inverse of the constant the chain rule would have produced on differentiation. Here \\(k = -1\\), so the prefactor is \\(-1\\)." }, { stepNumber: 2, description: "Simplify.", workingLatex: "= -e^{-x} + C", explanation: "Quick mental check: \\(\\frac{d}{dx}(-e^{-x}) = -(-1)e^{-x} = e^{-x}\\) ✓." } ], finalAnswer: "\\(-e^{-x} + C\\)." } },
  { id: "y2in1-013", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 13", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 3e^{4x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Pull the constant out.", workingLatex: "\\displaystyle\\int 3e^{4x}\\,dx = 3\\displaystyle\\int e^{4x}\\,dx", explanation: "Constant multiples factor straight through the integral, keeping the standard \\(e^{kx}\\) form clean." }, { stepNumber: 2, description: "Apply \\(\\displaystyle\\int e^{kx}\\,dx = \\frac{1}{k}e^{kx} + C\\) with \\(k = 4\\).", workingLatex: "3\\displaystyle\\int e^{4x}\\,dx = 3 \\cdot \\frac{1}{4}e^{4x} + C", explanation: "The \\(\\frac{1}{k}\\) factor of \\(\\frac{1}{4}\\) comes from undoing the chain-rule derivative of \\(e^{4x}\\), which would produce a \\(4\\) at the front." }, { stepNumber: 3, description: "Combine the constants.", workingLatex: "= \\frac{3}{4}e^{4x} + C", explanation: "\\(3 \\cdot \\frac{1}{4} = \\frac{3}{4}\\). Quick check: \\(\\frac{d}{dx}(\\frac{3}{4}e^{4x}) = \\frac{3}{4} \\cdot 4 e^{4x} = 3e^{4x}\\) ✓." } ], finalAnswer: "\\(\\frac{3}{4}e^{4x} + C\\)." } },
  { id: "y2in1-014", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 14", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 5e^{-2x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Pull the constant out.", workingLatex: "\\displaystyle\\int 5e^{-2x}\\,dx = 5\\displaystyle\\int e^{-2x}\\,dx", explanation: "Same as the previous question — constants factor through." }, { stepNumber: 2, description: "Apply \\(\\displaystyle\\int e^{kx}\\,dx = \\frac{1}{k}e^{kx} + C\\) with \\(k = -2\\).", workingLatex: "5\\displaystyle\\int e^{-2x}\\,dx = 5 \\cdot \\frac{1}{-2}e^{-2x} + C = -\\frac{5}{2}e^{-2x} + C", explanation: "\\(\\frac{1}{k} = -\\frac{1}{2}\\) brings in both the factor and a sign flip. Verify: \\(\\frac{d}{dx}(-\\frac{5}{2}e^{-2x}) = -\\frac{5}{2} \\cdot (-2)e^{-2x} = 5e^{-2x}\\) ✓." } ], finalAnswer: "\\(-\\frac{5}{2}e^{-2x} + C\\)." } },
  { id: "y2in1-015", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 15", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{x} \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "Recognise that the power rule misses this case.", workingLatex: "\\displaystyle\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} \\text{ is undefined at } n = -1", explanation: "Setting \\(n = -1\\) would divide by zero. The reciprocal \\(\\frac{1}{x} = x^{-1}\\) is therefore the one power that needs a special antiderivative." }, { stepNumber: 2, description: "Use the derivative of \\(\\ln|x|\\).", workingLatex: "\\frac{d}{dx}(\\ln|x|) = \\frac{1}{x} \\quad (x \\ne 0)", explanation: "On \\(x > 0\\), \\(\\frac{d}{dx}\\ln x = \\frac{1}{x}\\); on \\(x < 0\\), \\(\\frac{d}{dx}\\ln(-x) = \\frac{-1}{-x} = \\frac{1}{x}\\) (chain rule). Together \\(\\ln|x|\\) is an antiderivative on the whole domain \\(x \\ne 0\\)." }, { stepNumber: 3, description: "Write the antiderivative.", workingLatex: "\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x| + C", explanation: "The modulus is essential — \\(\\ln x\\) alone would only be defined for \\(x > 0\\), but \\(\\frac{1}{x}\\) exists for negative \\(x\\) too." } ], finalAnswer: "\\(\\ln|x| + C\\)." } },
  { id: "y2in1-016", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 16", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{3}{x} \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "Pull the constant out.", workingLatex: "\\displaystyle\\int \\frac{3}{x}\\,dx = 3\\displaystyle\\int \\frac{1}{x}\\,dx", explanation: "The factor of \\(3\\) factors out of the integral." }, { stepNumber: 2, description: "Apply the standard result \\(\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x| + C\\).", workingLatex: "= 3\\ln|x| + C", explanation: "A common slip is to drop the modulus signs around the \\(x\\) — always write \\(\\ln|x|\\), not \\(\\ln x\\), so the antiderivative is valid for negative \\(x\\) too." } ], finalAnswer: "\\(3\\ln|x| + C\\)." } },
  { id: "y2in1-017", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 17", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{5}{2x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite to expose the constant.", workingLatex: "\\frac{5}{2x} = \\frac{5}{2} \\cdot \\frac{1}{x}", explanation: "Separating the numerical constant \\(\\frac{5}{2}\\) from \\(\\frac{1}{x}\\) reduces this to a known standard integral." }, { stepNumber: 2, description: "Integrate using \\(\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x| + C\\).", workingLatex: "\\displaystyle\\int \\frac{5}{2} \\cdot \\frac{1}{x}\\,dx = \\frac{5}{2}\\ln|x| + C", explanation: "The constant \\(\\frac{5}{2}\\) just multiplies the standard antiderivative. Keep the modulus signs." } ], finalAnswer: "\\(\\frac{5}{2}\\ln|x| + C\\)." } },
  { id: "y2in1-018", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 18", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sin x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\cos x\\).", workingLatex: "\\frac{d}{dx}(\\cos x) = -\\sin x", explanation: "Cosine differentiates to minus sine — a one-fact memorise. Reading this in reverse tells us how to undo it." }, { stepNumber: 2, description: "Flip the sign to obtain the antiderivative of \\(\\sin x\\).", workingLatex: "\\frac{d}{dx}(-\\cos x) = \\sin x \\;\\Rightarrow\\; \\displaystyle\\int \\sin x\\,dx = -\\cos x + C", explanation: "Pull the minus from the derivative onto the antiderivative. This sign flip is the most common error students make with this integral." } ], finalAnswer: "\\(-\\cos x + C\\)." } },
  { id: "y2in1-019", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 19", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\cos x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\sin x\\).", workingLatex: "\\frac{d}{dx}(\\sin x) = \\cos x", explanation: "Sine differentiates cleanly to cosine — no minus sign here, unlike the cosine→sine case." }, { stepNumber: 2, description: "Read off the antiderivative.", workingLatex: "\\displaystyle\\int \\cos x\\,dx = \\sin x + C", explanation: "Because the derivative goes \\(\\sin \\to \\cos\\) with no sign flip, the integral goes \\(\\cos \\to \\sin\\) with no sign flip either. Don\\'t over-think this one." } ], finalAnswer: "\\(\\sin x + C\\)." } },
  { id: "y2in1-020", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 20", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sec^2 x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\tan x\\).", workingLatex: "\\frac{d}{dx}(\\tan x) = \\sec^2 x", explanation: "\\(\\tan x\\) differentiates to \\(\\sec^2 x\\) (a standard result you should have memorised). Reading this backwards gives the antiderivative." }, { stepNumber: 2, description: "Read off the antiderivative.", workingLatex: "\\displaystyle\\int \\sec^2 x\\,dx = \\tan x + C", explanation: "No sign or factor needed — the integrand is the exact derivative of \\(\\tan x\\)." } ], finalAnswer: "\\(\\tan x + C\\)." } },
  { id: "y2in1-021", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 21", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\csc^2 x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\cot x\\).", workingLatex: "\\frac{d}{dx}(\\cot x) = -\\csc^2 x", explanation: "\\(\\cot x\\) differentiates to \\(-\\csc^2 x\\) (note the minus). Reading this in reverse gives \\(\\displaystyle\\int -\\csc^2 x\\,dx = \\cot x\\)." }, { stepNumber: 2, description: "Flip the sign to get the antiderivative of \\(\\csc^2 x\\).", workingLatex: "\\displaystyle\\int \\csc^2 x\\,dx = -\\cot x + C", explanation: "The leading minus mirrors the minus in the derivative of \\(\\cot x\\). Easy to drop — keep it." } ], finalAnswer: "\\(-\\cot x + C\\)." } },
  { id: "y2in1-022", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 22", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sec x\\tan x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\sec x\\).", workingLatex: "\\frac{d}{dx}(\\sec x) = \\sec x\\tan x", explanation: "\\(\\sec x\\) differentiates to exactly \\(\\sec x\\tan x\\) — the product appears together because of the chain rule on \\(\\sec x = (\\cos x)^{-1}\\)." }, { stepNumber: 2, description: "Read off the antiderivative.", workingLatex: "\\displaystyle\\int \\sec x\\tan x\\,dx = \\sec x + C", explanation: "No sign or factor adjustments needed." } ], finalAnswer: "\\(\\sec x + C\\)." } },
  { id: "y2in1-023", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 23", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\csc x\\cot x \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\csc x\\).", workingLatex: "\\frac{d}{dx}(\\csc x) = -\\csc x\\cot x", explanation: "\\(\\csc x\\) differentiates to \\(-\\csc x\\cot x\\). The minus comes from the same chain-rule mechanic as for \\(\\sec x\\), but with the cofunction sign flip." }, { stepNumber: 2, description: "Flip the sign to obtain the antiderivative.", workingLatex: "\\displaystyle\\int \\csc x\\cot x\\,dx = -\\csc x + C", explanation: "Leading minus needed to undo the minus in the derivative of \\(\\csc x\\)." } ], finalAnswer: "\\(-\\csc x + C\\)." } },
  { id: "y2in1-024", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 24", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(2\\sin x - 3\\cos x\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term and factor out the constants.", workingLatex: "\\displaystyle\\int (2\\sin x - 3\\cos x)\\,dx = 2\\displaystyle\\int \\sin x\\,dx - 3\\displaystyle\\int \\cos x\\,dx", explanation: "Linearity: each term integrates separately, with its constant coefficient riding along outside." }, { stepNumber: 2, description: "Apply the two standard antiderivatives.", workingLatex: "= 2(-\\cos x) - 3(\\sin x) + C", explanation: "\\(\\displaystyle\\int \\sin x\\,dx = -\\cos x\\), \\(\\displaystyle\\int \\cos x\\,dx = \\sin x\\). The two constants of integration absorb into one \\(+C\\)." }, { stepNumber: 3, description: "Tidy up.", workingLatex: "= -2\\cos x - 3\\sin x + C", explanation: "Distribute the constants. Sign-check both terms: the \\(\\sin\\) integrates to a \\(\\cos\\)-with-minus; the \\(\\cos\\) keeps its sign as \\(\\sin\\)." } ], finalAnswer: "\\(-2\\cos x - 3\\sin x + C\\)." } },
  { id: "y2in1-025", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 25", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(\\sec^2 x + \\csc^2 x\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int (\\sec^2 x + \\csc^2 x)\\,dx = \\displaystyle\\int \\sec^2 x\\,dx + \\displaystyle\\int \\csc^2 x\\,dx", explanation: "Each term has its own standard antiderivative; the sum splits cleanly." }, { stepNumber: 2, description: "Apply each standard antiderivative.", workingLatex: "= \\tan x + (-\\cot x) + C = \\tan x - \\cot x + C", explanation: "\\(\\displaystyle\\int \\sec^2 x\\,dx = \\tan x\\), \\(\\displaystyle\\int \\csc^2 x\\,dx = -\\cot x\\). Mind the minus on the cotangent term." } ], finalAnswer: "\\(\\tan x - \\cot x + C\\)." } },
  { id: "y2in1-026", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 26", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(e^x + \\frac{1}{x}\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["mixed"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int (e^x + \\frac{1}{x})\\,dx = \\displaystyle\\int e^x\\,dx + \\displaystyle\\int \\frac{1}{x}\\,dx", explanation: "Both terms have textbook antiderivatives — split first, integrate second." }, { stepNumber: 2, description: "Apply each standard antiderivative.", workingLatex: "= e^x + \\ln|x| + C", explanation: "\\(\\displaystyle\\int e^x\\,dx = e^x\\), \\(\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x|\\). Keep the modulus signs in \\(\\ln|x|\\)." } ], finalAnswer: "\\(e^x + \\ln|x| + C\\)." } },
  { id: "y2in1-027", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 27", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(4\\sec^2 x - 2\\csc^2 x\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term and pull the constants out.", workingLatex: "\\displaystyle\\int (4\\sec^2 x - 2\\csc^2 x)\\,dx = 4\\displaystyle\\int \\sec^2 x\\,dx - 2\\displaystyle\\int \\csc^2 x\\,dx", explanation: "Linearity again. Each \\(\\sec^2\\) and \\(\\csc^2\\) integrates by the standard formulae." }, { stepNumber: 2, description: "Apply the standard antiderivatives.", workingLatex: "= 4\\tan x - 2(-\\cot x) + C", explanation: "\\(\\displaystyle\\int \\sec^2 x\\,dx = \\tan x\\); \\(\\displaystyle\\int \\csc^2 x\\,dx = -\\cot x\\). The two minuses on the second term will combine." }, { stepNumber: 3, description: "Simplify the double negative.", workingLatex: "= 4\\tan x + 2\\cot x + C", explanation: "Two minuses make a plus. The \\(\\cot\\)-term ends up positive after the cancellation." } ], finalAnswer: "\\(4\\tan x + 2\\cot x + C\\)." } },
  { id: "y2in1-028", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 28", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(x^2 + \\frac{1}{x}\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["mixed"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int (x^2 + \\frac{1}{x})\\,dx = \\displaystyle\\int x^2\\,dx + \\displaystyle\\int \\frac{1}{x}\\,dx", explanation: "A polynomial term and a reciprocal — each handled by its own standard antiderivative." }, { stepNumber: 2, description: "Apply the power rule and the log rule.", workingLatex: "= \\frac{x^3}{3} + \\ln|x| + C", explanation: "Power rule on \\(x^2\\) (giving \\(\\frac{x^3}{3}\\)); \\(\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x|\\). Two terms, one \\(+C\\)." } ], finalAnswer: "\\(\\frac{x^3}{3} + \\ln|x| + C\\)." } },
  { id: "y2in1-029", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 29", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{x^2 + 1}{x}\\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "Split the fraction term-by-term.", workingLatex: "\\frac{x^2 + 1}{x} = \\frac{x^2}{x} + \\frac{1}{x} = x + \\frac{1}{x}", explanation: "When the denominator is a single monomial, divide each term in the numerator by it. The trick is to break up the fraction before integrating — never integrate a quotient as is unless it is already a known form." }, { stepNumber: 2, description: "Set up the integral as two pieces.", workingLatex: "\\displaystyle\\int \\frac{x^2 + 1}{x}\\,dx = \\displaystyle\\int x\\,dx + \\displaystyle\\int \\frac{1}{x}\\,dx", explanation: "Each piece is a standard antiderivative." }, { stepNumber: 3, description: "Apply the power rule and the log rule.", workingLatex: "= \\frac{x^2}{2} + \\ln|x| + C", explanation: "Power rule with \\(n = 1\\) on the first term; standard log result on the second. Keep the modulus signs." } ], finalAnswer: "\\(\\frac{x^2}{2} + \\ln|x| + C\\)." } },
  { id: "y2in1-030", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 30", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{3x^2 - 2}{x^2}\\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Split the fraction term-by-term.", workingLatex: "\\frac{3x^2 - 2}{x^2} = \\frac{3x^2}{x^2} - \\frac{2}{x^2} = 3 - 2x^{-2}", explanation: "Divide each numerator term by \\(x^2\\). Rewrite \\(\\frac{2}{x^2}\\) as \\(2x^{-2}\\) so the power rule can be applied." }, { stepNumber: 2, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int (3 - 2x^{-2})\\,dx = 3x - 2 \\cdot \\frac{x^{-1}}{-1} + C", explanation: "\\(\\displaystyle\\int 3\\,dx = 3x\\); apply the power rule to \\(x^{-2}\\) with \\(n = -2\\), giving \\(\\frac{x^{-1}}{-1} = -\\frac{1}{x}\\)." }, { stepNumber: 3, description: "Simplify the signs.", workingLatex: "= 3x - 2(-\\frac{1}{x}) + C = 3x + \\frac{2}{x} + C", explanation: "The two minus signs on the second term cancel. Final answer is positive \\(\\frac{2}{x}\\)." } ], finalAnswer: "\\(3x + \\frac{2}{x} + C\\)." } },
  { id: "y2in1-031", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 31", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi} \\sin x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sin x\\,dx = -\\cos x \\;(+C)", explanation: "The constant of integration drops out in a definite integral, so we suppress it." }, { stepNumber: 2, description: "Apply the limits using the Fundamental Theorem of Calculus.", workingLatex: "\\displaystyle\\int_0^{\\pi} \\sin x\\,dx = \\big[-\\cos x\\big]_0^{\\pi} = -\\cos\\pi - (-\\cos 0)", explanation: "Substitute the upper limit, subtract the value at the lower limit. Bracket the antiderivative so the minus sign is unambiguous." }, { stepNumber: 3, description: "Evaluate the cosines.", workingLatex: "= -(-1) - (-1) = 1 + 1 = 2", explanation: "\\(\\cos\\pi = -1\\), \\(\\cos 0 = 1\\). Watch the cascade of minus signs — there are three to keep straight." } ], finalAnswer: "2." } },
  { id: "y2in1-032", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 32", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\cos x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\cos x\\,dx = \\sin x", explanation: "Standard result." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\sin x\\big]_0^{\\pi/2} = \\sin(\\frac{\\pi}{2}) - \\sin 0 = 1 - 0 = 1", explanation: "\\(\\sin(\\pi/2) = 1\\), \\(\\sin 0 = 0\\). One quick subtraction." } ], finalAnswer: "1." } },
  { id: "y2in1-033", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 33", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^1 e^x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int e^x\\,dx = e^x", explanation: "" }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[e^x\\big]_0^1 = e^1 - e^0 = e - 1", explanation: "\\(e^0 = 1\\). Leave the answer in exact form — don\\'t round to a decimal unless asked." } ], finalAnswer: "\\(e - 1\\)." } },
  { id: "y2in1-034", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 34", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_1^e \\frac{1}{x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x|", explanation: "The reciprocal integrates to natural log with absolute value." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\ln|x|\\big]_1^{e} = \\ln e - \\ln 1 = 1 - 0 = 1", explanation: "On the positive interval \\([1, e]\\) the modulus is redundant: \\(\\ln|x| = \\ln x\\). \\(\\ln e = 1\\) and \\(\\ln 1 = 0\\)." } ], finalAnswer: "1." } },
  { id: "y2in1-035", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 35", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/4} \\sec^2 x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sec^2 x\\,dx = \\tan x", explanation: "Standard result." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\tan x\\big]_0^{\\pi/4} = \\tan(\\frac{\\pi}{4}) - \\tan 0 = 1 - 0 = 1", explanation: "\\(\\tan(\\pi/4) = 1\\), \\(\\tan 0 = 0\\)." } ], finalAnswer: "1." } },
  { id: "y2in1-036", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 36", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_{\\pi/6}^{\\pi/3} \\csc^2 x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\csc^2 x\\,dx = -\\cot x", explanation: "Remember the leading minus — \\(\\frac{d}{dx}(\\cot x) = -\\csc^2 x\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[-\\cot x\\big]_{\\pi/6}^{\\pi/3} = -\\cot(\\frac{\\pi}{3}) - \\bigl(-\\cot(\\frac{\\pi}{6})\\bigr)", explanation: "Substitute the upper limit, subtract the value at the lower. Keep both minuses visible." }, { stepNumber: 3, description: "Evaluate the cotangents.", workingLatex: "= -\\frac{1}{\\sqrt 3} + \\sqrt{3}", explanation: "\\(\\cot(\\pi/3) = \\frac{1}{\\tan(\\pi/3)} = \\frac{1}{\\sqrt{3}}\\); \\(\\cot(\\pi/6) = \\frac{1}{\\tan(\\pi/6)} = \\sqrt{3}\\)." }, { stepNumber: 4, description: "Rationalise to the standard form.", workingLatex: "\\sqrt{3} - \\frac{1}{\\sqrt{3}} = \\frac{3 - 1}{\\sqrt{3}} = \\frac{2}{\\sqrt{3}} = \\frac{2\\sqrt{3}}{3}", explanation: "Common denominator is \\(\\sqrt{3}\\); rationalise by multiplying top and bottom by \\(\\sqrt{3}\\)." } ], finalAnswer: "\\(\\sqrt 3 - \\frac{1}{\\sqrt 3} = \\frac{2}{\\sqrt 3} = \\frac{2\\sqrt 3}{3}\\)." } },
  { id: "y2in1-037", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 37", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/3} \\sec x\\tan x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sec x\\tan x\\,dx = \\sec x", explanation: "Standard result: \\(\\sec x\\) differentiates to \\(\\sec x\\tan x\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\sec x\\big]_0^{\\pi/3} = \\sec(\\frac{\\pi}{3}) - \\sec 0", explanation: "Upper limit minus lower limit." }, { stepNumber: 3, description: "Evaluate the secants.", workingLatex: "= 2 - 1 = 1", explanation: "\\(\\sec(\\pi/3) = 1/\\cos(\\pi/3) = 1/(1/2) = 2\\); \\(\\sec 0 = 1\\)." } ], finalAnswer: "1." } },
  { id: "y2in1-038", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 38", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_1^2 x^2 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative by the power rule.", workingLatex: "\\displaystyle\\int x^2\\,dx = \\frac{x^3}{3}", explanation: "\\(n + 1 = 3\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\Big[\\frac{x^3}{3}\\Big]_1^2 = \\frac{2^3}{3} - \\frac{1^3}{3} = \\frac{8}{3} - \\frac{1}{3} = \\frac{7}{3}", explanation: "Plug in the upper and lower limits, subtract, simplify with a common denominator." } ], finalAnswer: "\\(\\frac{7}{3}\\)." } },
  { id: "y2in1-039", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 39", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^2 \\left(3x^2 - 4x + 1\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "Integrate term-by-term using the power rule.", workingLatex: "\\displaystyle\\int (3x^2 - 4x + 1)\\,dx = x^3 - 2x^2 + x", explanation: "\\(\\displaystyle\\int 3x^2\\,dx = x^3\\), \\(\\displaystyle\\int 4x\\,dx = 2x^2\\), \\(\\displaystyle\\int 1\\,dx = x\\). Constants merge into one which drops out in the definite integral." }, { stepNumber: 2, description: "Evaluate at the upper limit \\(x = 2\\).", workingLatex: "(2)^3 - 2(2)^2 + 2 = 8 - 8 + 2 = 2", explanation: "Plug in \\(x = 2\\) carefully — the two \\(8\\)s cancel, leaving the constant \\(+2\\)." }, { stepNumber: 3, description: "Evaluate at the lower limit \\(x = 0\\).", workingLatex: "(0)^3 - 2(0)^2 + 0 = 0", explanation: "Every term is zero at \\(x = 0\\)." }, { stepNumber: 4, description: "Subtract.", workingLatex: "2 - 0 = 2", explanation: "Upper-limit value minus lower-limit value." } ], finalAnswer: "2." } },
  { id: "y2in1-040", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 40", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_{-1}^{1} e^{-x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative using \\(\\displaystyle\\int e^{kx}\\,dx = \\frac{1}{k}e^{kx}\\).", workingLatex: "\\displaystyle\\int e^{-x}\\,dx = -e^{-x}", explanation: "With \\(k = -1\\), the factor \\(\\frac{1}{k} = -1\\) appears out front." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[-e^{-x}\\big]_{-1}^{1} = -e^{-1} - (-e^{1}) = -e^{-1} + e", explanation: "Two minuses combine into a plus on the lower-limit term." }, { stepNumber: 3, description: "Tidy the form.", workingLatex: "= e - e^{-1} = e - \\frac{1}{e}", explanation: "Equivalent forms; both acceptable." } ], finalAnswer: "\\(e - \\frac{1}{e}\\)." } },
  { id: "y2in1-041", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 41", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(6x^5 - 4x^3\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term and pull constants out.", workingLatex: "\\displaystyle\\int (6x^5 - 4x^3)\\,dx = 6\\displaystyle\\int x^5\\,dx - 4\\displaystyle\\int x^3\\,dx", explanation: "Linearity of integration." }, { stepNumber: 2, description: "Apply the power rule to each.", workingLatex: "= 6 \\cdot \\frac{x^6}{6} - 4 \\cdot \\frac{x^4}{4} + C", explanation: "\\(n+1 = 6\\) for the first; \\(n+1 = 4\\) for the second. The constants will cancel cleanly." }, { stepNumber: 3, description: "Simplify.", workingLatex: "= x^6 - x^4 + C", explanation: "\\(\\frac{6}{6} = 1\\), \\(\\frac{4}{4} = 1\\)." } ], finalAnswer: "\\(x^6 - x^4 + C\\)." } },
  { id: "y2in1-042", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 42", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{3}{x^4} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite as a power of \\(x\\).", workingLatex: "\\frac{3}{x^4} = 3x^{-4}", explanation: "The power rule needs \\(x^n\\) form. \\(\\frac{1}{x^4} = x^{-4}\\)." }, { stepNumber: 2, description: "Apply the power rule with \\(n = -4\\).", workingLatex: "\\displaystyle\\int 3x^{-4}\\,dx = 3 \\cdot \\frac{x^{-3}}{-3} + C", explanation: "\\(n+1 = -3\\). The negative denominator will flip the sign of the answer." }, { stepNumber: 3, description: "Simplify.", workingLatex: "= -x^{-3} + C = -\\frac{1}{x^3} + C", explanation: "\\(\\frac{3}{-3} = -1\\). Convert the negative power back to a fraction." } ], finalAnswer: "\\(-\\frac{1}{x^3} + C\\)." } },
  { id: "y2in1-043", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 43", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sqrt[3]{x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["power"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the cube root as a power.", workingLatex: "\\sqrt[3]{x} = x^{\\tfrac{1}{3}}", explanation: "\\(\\sqrt[3]{x}\\) is exactly \\(x^{\\tfrac{1}{3}}\\) — the standard fractional-exponent rewrite." }, { stepNumber: 2, description: "Apply the power rule with \\(n = \\frac{1}{3}\\).", workingLatex: "\\displaystyle\\int x^{\\tfrac{1}{3}}\\,dx = \\frac{x^{\\tfrac{4}{3}}}{4/3} + C", explanation: "\\(n + 1 = \\frac{4}{3}\\). Keep the fraction symbolic." }, { stepNumber: 3, description: "Simplify the compound fraction.", workingLatex: "= \\frac{3}{4}x^{\\tfrac{4}{3}} + C", explanation: "Dividing by \\(\\frac{4}{3}\\) is multiplying by \\(\\frac{3}{4}\\)." } ], finalAnswer: "\\(\\frac{3}{4}x^{\\tfrac{4}{3}} + C\\)." } },
  { id: "y2in1-044", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 44", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 5e^{-3x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Pull the constant out.", workingLatex: "\\displaystyle\\int 5e^{-3x}\\,dx = 5\\displaystyle\\int e^{-3x}\\,dx", explanation: "Standard first step." }, { stepNumber: 2, description: "Apply \\(\\displaystyle\\int e^{kx}\\,dx = \\frac{1}{k}e^{kx} + C\\) with \\(k = -3\\).", workingLatex: "5 \\cdot \\frac{1}{-3}e^{-3x} + C = -\\frac{5}{3}e^{-3x} + C", explanation: "The \\(\\frac{1}{k} = -\\frac{1}{3}\\) factor flips the sign. Verify: \\(\\frac{d}{dx}(-\\frac{5}{3}e^{-3x}) = -\\frac{5}{3} \\cdot (-3)e^{-3x} = 5e^{-3x}\\) ✓." } ], finalAnswer: "\\(-\\frac{5}{3}e^{-3x} + C\\)." } },
  { id: "y2in1-045", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 45", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{e^x + e^{-x}}{2} \\,dx \\) (recognise as \\(\\cosh x\\)).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["exp", "hyperbolic"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term and factor out \\(\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int \\frac{e^x + e^{-x}}{2}\\,dx = \\frac{1}{2}\\displaystyle\\int e^x\\,dx + \\frac{1}{2}\\displaystyle\\int e^{-x}\\,dx", explanation: "The denominator \\(2\\) is a constant; it factors out (or appears as a leading \\(\\frac{1}{2}\\))." }, { stepNumber: 2, description: "Apply the standard exponential antiderivatives.", workingLatex: "= \\frac{1}{2}\\bigl(e^x\\bigr) + \\frac{1}{2}\\bigl(-e^{-x}\\bigr) + C = \\frac{1}{2}e^x - \\frac{1}{2}e^{-x} + C", explanation: "\\(\\displaystyle\\int e^x\\,dx = e^x\\); \\(\\displaystyle\\int e^{-x}\\,dx = -e^{-x}\\). The minus on the second term comes from the \\(\\frac{1}{k}\\) with \\(k = -1\\)." }, { stepNumber: 3, description: "Combine into the compact form.", workingLatex: "= \\frac{e^x - e^{-x}}{2} + C", explanation: "This is \\(\\sinh x + C\\), which is exactly what we expect since the integrand was \\(\\cosh x\\)." } ], finalAnswer: "\\(\\frac{e^x - e^{-x}}{2} + C\\)." } },
  { id: "y2in1-046", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 46", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(4\\sin x + 6\\cos x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term and pull constants out.", workingLatex: "\\displaystyle\\int (4\\sin x + 6\\cos x)\\,dx = 4\\displaystyle\\int \\sin x\\,dx + 6\\displaystyle\\int \\cos x\\,dx", explanation: "Linearity." }, { stepNumber: 2, description: "Apply the standard antiderivatives.", workingLatex: "= 4(-\\cos x) + 6(\\sin x) + C = -4\\cos x + 6\\sin x + C", explanation: "\\(\\displaystyle\\int \\sin x\\,dx = -\\cos x\\); \\(\\displaystyle\\int \\cos x\\,dx = \\sin x\\). Mind the minus on the cosine term." } ], finalAnswer: "\\(-4\\cos x + 6\\sin x + C\\)." } },
  { id: "y2in1-047", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 47", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{3x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "Pull the constant out.", workingLatex: "\\frac{1}{3x} = \\frac{1}{3} \\cdot \\frac{1}{x} \\;\\Rightarrow\\; \\displaystyle\\int \\frac{1}{3x}\\,dx = \\frac{1}{3}\\displaystyle\\int \\frac{1}{x}\\,dx", explanation: "Separate the numerical \\(\\frac{1}{3}\\) from the standard \\(\\frac{1}{x}\\) form." }, { stepNumber: 2, description: "Apply the log rule.", workingLatex: "= \\frac{1}{3}\\ln|x| + C", explanation: "The constant just multiplies the standard antiderivative. Keep the modulus." } ], finalAnswer: "\\(\\frac{1}{3}\\ln|x| + C\\)." } },
  { id: "y2in1-048", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 48", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(2\\sec^2 x + 3\\sec x\\tan x\\right)\\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term, factor constants.", workingLatex: "\\displaystyle\\int (2\\sec^2 x + 3\\sec x\\tan x)\\,dx = 2\\displaystyle\\int \\sec^2 x\\,dx + 3\\displaystyle\\int \\sec x\\tan x\\,dx", explanation: "Two standard antiderivatives, side by side." }, { stepNumber: 2, description: "Apply each.", workingLatex: "= 2\\tan x + 3\\sec x + C", explanation: "\\(\\displaystyle\\int \\sec^2 x\\,dx = \\tan x\\); \\(\\displaystyle\\int \\sec x\\tan x\\,dx = \\sec x\\). No sign flips required for these two." } ], finalAnswer: "\\(2\\tan x + 3\\sec x + C\\)." } },
  { id: "y2in1-049", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 49", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(\\csc^2 x - \\csc x\\cot x\\right)\\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int (\\csc^2 x - \\csc x\\cot x)\\,dx = \\displaystyle\\int \\csc^2 x\\,dx - \\displaystyle\\int \\csc x\\cot x\\,dx", explanation: "Linearity; each piece has a known antiderivative." }, { stepNumber: 2, description: "Apply each standard antiderivative.", workingLatex: "= (-\\cot x) - (-\\csc x) + C", explanation: "\\(\\displaystyle\\int \\csc^2 x\\,dx = -\\cot x\\); \\(\\displaystyle\\int \\csc x\\cot x\\,dx = -\\csc x\\). Two minus signs to track." }, { stepNumber: 3, description: "Simplify the signs.", workingLatex: "= -\\cot x + \\csc x + C", explanation: "Two minuses make a plus on the cosecant term." } ], finalAnswer: "\\(-\\cot x + \\csc x + C\\)." } },
  { id: "y2in1-050", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 50", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(\\frac{1}{x} + \\frac{1}{x^2}\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["mixed"], workedSolution: { steps: [ { stepNumber: 1, description: "Split and rewrite each term in standard form.", workingLatex: "\\frac{1}{x} + \\frac{1}{x^2} = \\frac{1}{x} + x^{-2}", explanation: "The first term is the log standard; the second is a power-rule term once rewritten as \\(x^{-2}\\)." }, { stepNumber: 2, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int \\frac{1}{x}\\,dx + \\displaystyle\\int x^{-2}\\,dx = \\ln|x| + \\frac{x^{-1}}{-1} + C", explanation: "Log rule for the first; power rule with \\(n = -2\\) for the second (\\(n+1 = -1\\))." }, { stepNumber: 3, description: "Simplify.", workingLatex: "= \\ln|x| - \\frac{1}{x} + C", explanation: "\\(\\frac{1}{-1} = -1\\). Convert \\(x^{-1}\\) to the fraction form for presentation." } ], finalAnswer: "\\(\\ln|x| - \\frac{1}{x} + C\\)." } },
  { id: "y2in1-051", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 51", difficulty: "Standard", answerType: "expression", questionText: "Given \\(f\\'(x) = e^x\\) and \\(f(0) = 3\\), find \\(f(x)\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["ivp", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Integrate \\(f'(x)\\) to find the general form of \\(f\\).", workingLatex: "f(x) = \\displaystyle\\int e^x\\,dx = e^x + C", explanation: "Antidifferentiation introduces an arbitrary constant — this is the family of curves with the given derivative." }, { stepNumber: 2, description: "Use the initial condition \\(f(0) = 3\\) to pin down \\(C\\).", workingLatex: "f(0) = e^0 + C = 1 + C = 3 \\;\\Rightarrow\\; C = 2", explanation: "\\(e^0 = 1\\). Solve for the constant by substituting the given point." }, { stepNumber: 3, description: "Write the particular solution.", workingLatex: "f(x) = e^x + 2", explanation: "This is the unique curve in the family that passes through \\((0, 3)\\)." } ], finalAnswer: "\\(f(x) = e^x + 2\\)." } },
  { id: "y2in1-052", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 52", difficulty: "Standard", answerType: "expression", questionText: "\\(f\\'(x) = \\cos x, f(0) = 1\\). Find \\(f\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["ivp", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Integrate to find the family of solutions.", workingLatex: "f(x) = \\displaystyle\\int \\cos x\\,dx = \\sin x + C", explanation: "" }, { stepNumber: 2, description: "Use \\(f(0) = 1\\) to find \\(C\\).", workingLatex: "f(0) = \\sin 0 + C = 0 + C = 1 \\;\\Rightarrow\\; C = 1", explanation: "\\(\\sin 0 = 0\\), so the constant equals the given output." }, { stepNumber: 3, description: "Write the particular solution.", workingLatex: "f(x) = \\sin x + 1", explanation: "" } ], finalAnswer: "\\(f(x) = \\sin x + 1\\)." } },
  { id: "y2in1-053", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 53", difficulty: "Standard", answerType: "expression", questionText: "Find \\(y\\) given \\(\\frac{dy}{dx} = \\sec^2 x\\) and curve passes through \\(\\left(0, 2\\right)\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["ivp", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Integrate to find the family of solutions.", workingLatex: "y = \\displaystyle\\int \\sec^2 x\\,dx = \\tan x + C", explanation: "Standard antiderivative." }, { stepNumber: 2, description: "Substitute the point \\((0, 2)\\) to find \\(C\\).", workingLatex: "2 = \\tan 0 + C = 0 + C \\;\\Rightarrow\\; C = 2", explanation: "\\(\\tan 0 = 0\\). The constant is read straight off the \\(y\\)-intercept here." }, { stepNumber: 3, description: "Write the particular solution.", workingLatex: "y = \\tan x + 2", explanation: "" } ], finalAnswer: "\\(y = \\tan x + 2\\)." } },
  { id: "y2in1-054", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 54", difficulty: "Standard", answerType: "expression", questionText: "Find \\(y\\) given \\(\\frac{dy}{dx} = \\frac{1}{x}\\), passing through \\(\\left(e, 4\\right)\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["ivp", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Integrate to find the family of solutions.", workingLatex: "y = \\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x| + C", explanation: "" }, { stepNumber: 2, description: "Substitute \\((e, 4)\\) to find \\(C\\).", workingLatex: "4 = \\ln|e| + C = 1 + C \\;\\Rightarrow\\; C = 3", explanation: "\\(\\ln e = 1\\) (\\(|e|\\) is just \\(e\\), positive)." }, { stepNumber: 3, description: "Write the particular solution.", workingLatex: "y = \\ln|x| + 3", explanation: "" } ], finalAnswer: "\\(y = \\ln|x| + 3\\)." } },
  { id: "y2in1-055", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 55", difficulty: "Challenge", answerType: "expression", questionText: "Acceleration \\(a(t) = e^t\\). Find velocity given \\(v(0) = 0\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["ivp", "exp", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the kinematic relationship.", workingLatex: "a(t) = \\frac{dv}{dt} \\;\\Rightarrow\\; v(t) = \\displaystyle\\int a(t)\\,dt", explanation: "Velocity is the antiderivative of acceleration — integrating \\(a\\) recovers \\(v\\) up to a constant." }, { stepNumber: 2, description: "Integrate the acceleration.", workingLatex: "v(t) = \\displaystyle\\int e^t\\,dt = e^t + C", explanation: "\\(e^t\\) is its own antiderivative; \\(C\\) is an arbitrary constant determined by the initial condition." }, { stepNumber: 3, description: "Apply \\(v(0) = 0\\) to find \\(C\\).", workingLatex: "v(0) = e^0 + C = 1 + C = 0 \\;\\Rightarrow\\; C = -1", explanation: "\\(e^0 = 1\\); the initial-velocity condition forces \\(C = -1\\) so that \\(v\\) starts at zero." }, { stepNumber: 4, description: "Write the velocity function.", workingLatex: "v(t) = e^t - 1", explanation: "Sanity check: at \\(t = 0\\), \\(v = 1 - 1 = 0\\) ✓; the velocity grows exponentially from rest." } ], finalAnswer: "\\(v(t) = e^t - 1\\)." } },
  { id: "y2in1-056", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 56", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(\\cos x - \\sin x\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int (\\cos x - \\sin x)\\,dx = \\displaystyle\\int \\cos x\\,dx - \\displaystyle\\int \\sin x\\,dx", explanation: "Linearity." }, { stepNumber: 2, description: "Apply the standard antiderivatives.", workingLatex: "= \\sin x - (-\\cos x) + C = \\sin x + \\cos x + C", explanation: "\\(\\displaystyle\\int \\cos x\\,dx = \\sin x\\); \\(\\displaystyle\\int \\sin x\\,dx = -\\cos x\\). The minus on \\(\\sin x\\) becomes a plus when distributed." } ], finalAnswer: "\\(\\sin x + \\cos x + C\\)." } },
  { id: "y2in1-057", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 57", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(e^x - \\frac{2}{x}\\right)\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["mixed"], workedSolution: { steps: [ { stepNumber: 1, description: "Split term-by-term, pull constants out.", workingLatex: "\\displaystyle\\int (e^x - \\frac{2}{x})\\,dx = \\displaystyle\\int e^x\\,dx - 2\\displaystyle\\int \\frac{1}{x}\\,dx", explanation: "Standard split." }, { stepNumber: 2, description: "Apply the two standard antiderivatives.", workingLatex: "= e^x - 2\\ln|x| + C", explanation: "\\(\\displaystyle\\int e^x\\,dx = e^x\\); \\(\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x|\\). The factor of \\(2\\) multiplies the log term." } ], finalAnswer: "\\(e^x - 2\\ln|x| + C\\)." } },
  { id: "y2in1-058", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 58", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{x^3 - 3x + 2}{x^2}\\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["log", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "Divide each numerator term by \\(x^2\\).", workingLatex: "\\frac{x^3 - 3x + 2}{x^2} = \\frac{x^3}{x^2} - \\frac{3x}{x^2} + \\frac{2}{x^2} = x - \\frac{3}{x} + 2x^{-2}", explanation: "Split before integrating. Rewrite the last term as \\(2x^{-2}\\) so the power rule applies." }, { stepNumber: 2, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int \\bigl(x - \\frac{3}{x} + 2x^{-2}\\bigr)\\,dx = \\displaystyle\\int x\\,dx - 3\\displaystyle\\int \\frac{1}{x}\\,dx + 2\\displaystyle\\int x^{-2}\\,dx", explanation: "Each piece uses a standard rule." }, { stepNumber: 3, description: "Apply the three rules.", workingLatex: "= \\frac{x^2}{2} - 3\\ln|x| + 2 \\cdot \\frac{x^{-1}}{-1} + C", explanation: "Power rule for the first and third; log rule for the second." }, { stepNumber: 4, description: "Simplify the third term.", workingLatex: "= \\frac{x^2}{2} - 3\\ln|x| - \\frac{2}{x} + C", explanation: "\\(\\frac{2}{-1}x^{-1} = -2x^{-1} = -\\frac{2}{x}\\)." } ], finalAnswer: "\\(\\frac{x^2}{2} - 3\\ln|x| - \\frac{2}{x} + C\\)." } },
  { id: "y2in1-059", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 59", difficulty: "Challenge", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{\\left(\\sqrt x + 1\\right)^2}{x}\\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["log", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "Expand the square in the numerator.", workingLatex: "(\\sqrt{x} + 1)^2 = x + 2\\sqrt{x} + 1", explanation: "\\((a+b)^2 = a^2 + 2ab + b^2\\) with \\(a = \\sqrt{x}\\), \\(b = 1\\). Don\\'t skip this — keeping the square shut wastes a step." }, { stepNumber: 2, description: "Divide each numerator term by \\(x\\).", workingLatex: "\\frac{x + 2\\sqrt{x} + 1}{x} = 1 + \\frac{2\\sqrt{x}}{x} + \\frac{1}{x} = 1 + 2x^{-\\tfrac{1}{2}} + \\frac{1}{x}", explanation: "\\(\\frac{\\sqrt{x}}{x} = \\frac{x^{\\tfrac{1}{2}}}{x} = x^{-\\tfrac{1}{2}}\\). Rewrite everything as a sum of standard forms." }, { stepNumber: 3, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int \\bigl(1 + 2x^{-\\tfrac{1}{2}} + \\frac{1}{x}\\bigr)\\,dx = x + 2 \\cdot \\frac{x^{\\tfrac{1}{2}}}{1/2} + \\ln|x| + C", explanation: "Power rule on \\(x^{-\\tfrac{1}{2}}\\) gives \\(n+1 = \\frac{1}{2}\\); log rule on \\(\\frac{1}{x}\\)." }, { stepNumber: 4, description: "Simplify the middle term.", workingLatex: "= x + 4\\sqrt{x} + \\ln|x| + C", explanation: "\\(\\frac{2}{1/2} = 4\\); \\(x^{\\tfrac{1}{2}} = \\sqrt{x}\\)." } ], finalAnswer: "\\(x + 4\\sqrt x + \\ln|x| + C\\)." } },
  { id: "y2in1-060", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 60", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{e^{2x} - e^x}{e^x}\\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Simplify the integrand using \\(\\frac{e^a}{e^b} = e^{a-b}\\).", workingLatex: "\\frac{e^{2x} - e^x}{e^x} = \\frac{e^{2x}}{e^x} - \\frac{e^x}{e^x} = e^{x} - 1", explanation: "\\(\\frac{e^{2x}}{e^x} = e^{2x - x} = e^x\\); \\(\\frac{e^x}{e^x} = 1\\). Always simplify before integrating." }, { stepNumber: 2, description: "Integrate the simplified form.", workingLatex: "\\displaystyle\\int (e^x - 1)\\,dx = e^x - x + C", explanation: "Standard antiderivatives; the \\(-1\\) gives \\(-x\\)." } ], finalAnswer: "\\(e^x - x + C\\)." } },
  { id: "y2in1-061", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 61", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_1^4 \\sqrt x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the radical and integrate.", workingLatex: "\\displaystyle\\int \\sqrt{x}\\,dx = \\displaystyle\\int x^{\\tfrac{1}{2}}\\,dx = \\frac{x^{\\tfrac{3}{2}}}{3/2} = \\frac{2}{3}x^{\\tfrac{3}{2}}", explanation: "\\(\\sqrt{x} = x^{\\tfrac{1}{2}}\\); power rule with \\(n+1 = \\frac{3}{2}\\); dividing by \\(\\frac{3}{2}\\) is multiplying by \\(\\frac{2}{3}\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\Big[\\frac{2}{3}x^{\\tfrac{3}{2}}\\Big]_1^4 = \\frac{2}{3}\\bigl(4^{\\tfrac{3}{2}} - 1^{\\tfrac{3}{2}}\\bigr)", explanation: "Factor out the \\(\\frac{2}{3}\\) so the arithmetic is cleaner." }, { stepNumber: 3, description: "Evaluate the powers and simplify.", workingLatex: "= \\frac{2}{3}(8 - 1) = \\frac{2}{3} \\cdot 7 = \\frac{14}{3}", explanation: "\\(4^{\\tfrac{3}{2}} = (\\sqrt{4})^3 = 2^3 = 8\\); \\(1^{\\tfrac{3}{2}} = 1\\)." } ], finalAnswer: "\\(\\frac{14}{3}\\)." } },
  { id: "y2in1-062", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 62", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/6} \\sec x\\tan x \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sec x\\tan x\\,dx = \\sec x", explanation: "" }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\sec x\\big]_0^{\\pi/6} = \\sec(\\frac{\\pi}{6}) - \\sec 0", explanation: "" }, { stepNumber: 3, description: "Evaluate the secants.", workingLatex: "\\sec(\\frac{\\pi}{6}) = \\frac{1}{\\cos(\\pi/6)} = \\frac{1}{\\sqrt{3}/2} = \\frac{2}{\\sqrt{3}} = \\frac{2\\sqrt{3}}{3}; \\quad \\sec 0 = 1", explanation: "\\(\\cos(\\pi/6) = \\frac{\\sqrt{3}}{2}\\); reciprocate and rationalise." }, { stepNumber: 4, description: "Subtract.", workingLatex: "= \\frac{2\\sqrt{3}}{3} - 1", explanation: "Leave in exact form." } ], finalAnswer: "\\(\\frac{2\\sqrt 3}{3} - 1\\)." } },
  { id: "y2in1-063", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 63", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/3} \\sec^2 x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sec^2 x\\,dx = \\tan x", explanation: "" }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\tan x\\big]_0^{\\pi/3} = \\tan(\\frac{\\pi}{3}) - \\tan 0 = \\sqrt{3} - 0 = \\sqrt{3}", explanation: "\\(\\tan(\\pi/3) = \\sqrt{3}\\), \\(\\tan 0 = 0\\)." } ], finalAnswer: "\\(\\sqrt 3\\)." } },
  { id: "y2in1-064", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 64", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\ln 2} e^x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int e^x\\,dx = e^x", explanation: "" }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[e^x\\big]_0^{\\ln 2} = e^{\\ln 2} - e^0 = 2 - 1 = 1", explanation: "\\(e^{\\ln 2} = 2\\) (cancellation of exp and log); \\(e^0 = 1\\)." } ], finalAnswer: "1." } },
  { id: "y2in1-065", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 65", difficulty: "Foundation", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_{-\\pi/2}^{\\pi/2} \\cos x \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\cos x\\,dx = \\sin x", explanation: "" }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\sin x\\big]_{-\\pi/2}^{\\pi/2} = \\sin(\\frac{\\pi}{2}) - \\sin(-\\frac{\\pi}{2}) = 1 - (-1) = 2", explanation: "\\(\\sin(\\pi/2) = 1\\); \\(\\sin(-\\pi/2) = -1\\) (sine is odd). The two minuses combine." } ], finalAnswer: "2." } },
  { id: "y2in1-066", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 66", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_1^{e^2} \\frac{1}{x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x|", explanation: "" }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\big[\\ln|x|\\big]_1^{e^2} = \\ln(e^2) - \\ln 1 = 2 - 0 = 2", explanation: "\\(\\ln(e^2) = 2\\) by the log power rule (or because \\(\\ln\\) is the inverse of \\(\\exp\\)); \\(\\ln 1 = 0\\)." } ], finalAnswer: "2." } },
  { id: "y2in1-067", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 67", difficulty: "Standard", answerType: "expression", questionText: "Find the area under \\(y = \\frac{1}{x}\\) for \\(1 \\le x \\le 3\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "log", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the area as a definite integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_1^3 \\frac{1}{x}\\,dx", explanation: "On \\(1 \\le x \\le 3\\) the curve \\(y = \\frac{1}{x}\\) is positive, so the unsigned area equals the definite integral." }, { stepNumber: 2, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x|", explanation: "" }, { stepNumber: 3, description: "Apply the limits and simplify.", workingLatex: "\\big[\\ln|x|\\big]_1^3 = \\ln 3 - \\ln 1 = \\ln 3 - 0 = \\ln 3", explanation: "\\(\\ln 1 = 0\\). The answer in exact form is \\(\\ln 3\\); a numerical approximation is \\(\\approx 1.099\\)." } ], finalAnswer: "\\(\\ln 3\\) (\\(\\approx 1.099\\))." } },
  { id: "y2in1-068", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 68", difficulty: "Foundation", answerType: "expression", questionText: "Find the area under \\(y = e^x\\) from \\(x = 0\\) to \\(x = 1\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "exp", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the area as a definite integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^1 e^x\\,dx", explanation: "\\(e^x > 0\\) on \\([0, 1]\\), so the area is the definite integral." }, { stepNumber: 2, description: "Integrate and apply the limits.", workingLatex: "\\big[e^x\\big]_0^1 = e^1 - e^0 = e - 1", explanation: "\\(e^0 = 1\\); leave the answer exact." } ], finalAnswer: "\\(e - 1\\)." } },
  { id: "y2in1-069", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 69", difficulty: "Standard", answerType: "expression", questionText: "Find the area under \\(y = \\cos x\\) from 0 to \\(\\pi/4\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite", "trig", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the area as a definite integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^{\\pi/4} \\cos x\\,dx", explanation: "\\(\\cos x > 0\\) on \\([0, \\pi/4]\\), so the integral gives the unsigned area directly." }, { stepNumber: 2, description: "Integrate and apply the limits.", workingLatex: "\\big[\\sin x\\big]_0^{\\pi/4} = \\sin(\\frac{\\pi}{4}) - \\sin 0 = \\frac{\\sqrt{2}}{2} - 0 = \\frac{\\sqrt{2}}{2}", explanation: "\\(\\sin(\\pi/4) = \\frac{\\sqrt{2}}{2}\\). Leave in exact form." } ], finalAnswer: "\\(\\frac{\\sqrt 2}{2}\\)." } },
  { id: "y2in1-070", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 70", difficulty: "Foundation", answerType: "expression", questionText: "Explain why \\(\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x| + C\\) rather than \\(\\ln x + C\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the domain of \\(\\ln x\\).", workingLatex: "\\ln x \\text{ is defined only for } x > 0", explanation: "The natural logarithm \\(\\ln x\\) is not defined for \\(x \\le 0\\), so \\(\\ln x + C\\) cannot be the antiderivative of \\(\\frac{1}{x}\\) on the whole domain." }, { stepNumber: 2, description: "Note that \\(\\frac{1}{x}\\) is defined for every \\(x \\ne 0\\).", workingLatex: "\\frac{1}{x} \\text{ exists for } x > 0 \\text{ AND } x < 0", explanation: "So its antiderivative had better be defined wherever the integrand is — and that includes negative \\(x\\)." }, { stepNumber: 3, description: "Differentiate \\(\\ln|x|\\) on both halves of the domain.", workingLatex: "x > 0:\\; \\frac{d}{dx}\\ln x = \\frac{1}{x}; \\qquad x < 0:\\; \\frac{d}{dx}\\ln(-x) = \\frac{-1}{-x} = \\frac{1}{x}", explanation: "On \\(x < 0\\), \\(|x| = -x\\) and the chain rule gives the same \\(\\frac{1}{x}\\). So \\(\\ln|x|\\) is an antiderivative on both halves." }, { stepNumber: 4, description: "Conclude.", workingLatex: "\\displaystyle\\int \\frac{1}{x}\\,dx = \\ln|x| + C \\quad \\text{(for } x \\ne 0\\text{)}", explanation: "The modulus is needed to cover negative \\(x\\); without it the formula would only be valid on the positive half-line." } ], finalAnswer: "Absolute value covers negative \\(x\\) too." } },
  { id: "y2in1-071", topicRef: "y2in1", topicTitle: "Integrating Standard Functions 71", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{5e^x - 3}{e^x}\\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Simplify the integrand term-by-term.", workingLatex: "\\frac{5e^x - 3}{e^x} = \\frac{5e^x}{e^x} - \\frac{3}{e^x} = 5 - 3e^{-x}", explanation: "\\(\\frac{5e^x}{e^x} = 5\\); \\(\\frac{3}{e^x} = 3e^{-x}\\). Always simplify before integrating." }, { stepNumber: 2, description: "Integrate term-by-term.", workingLatex: "\\displaystyle\\int (5 - 3e^{-x})\\,dx = 5x - 3 \\cdot \\frac{1}{-1}e^{-x} + C", explanation: "\\(\\displaystyle\\int 5\\,dx = 5x\\); \\(\\displaystyle\\int e^{-x}\\,dx = -e^{-x}\\) (using \\(\\frac{1}{k}\\) with \\(k = -1\\))." }, { stepNumber: 3, description: "Simplify the signs.", workingLatex: "= 5x + 3e^{-x} + C", explanation: "The two minus signs on the second term combine to a plus." } ], finalAnswer: "\\(5x + 3e^{-x} + C\\)." } },
];
